package pl.zagranietyper.repository;import java.sql.*;import java.util.*;import java.util.regex.Pattern;
/** Completed fixtures referenced by current pending player-dependent markets. */
public final class FootballFixturePlayerStatisticsTargetSelector {private static final Pattern PLAYER=Pattern.compile("strzeli|golem|asyst|strza|celn|faul|kart|upomn|spalon|save|obron|interwenc|tackl|odbior|podan|drybl|bramkar");private final Database db;public FootballFixturePlayerStatisticsTargetSelector(Database d){db=d;}public List<Long>findTargets(){String q="SELECT f.fixture_id,lower(bl.tip_title) title FROM bet_legs bl JOIN bets b ON b.id=bl.bet_id AND b.active JOIN api_football_fixtures f ON f.fixture_id=bl.resolved_external_event_id::bigint WHERE bl.active AND bl.resolved_provider='API_FOOTBALL' AND bl.settlement_status='PENDING' AND bl.settlement_source='NONE' AND f.status_short IN('FT','AET','PEN') ORDER BY f.fixture_id";try(Connection c=db.openConnection()){c.setReadOnly(true);try(var p=c.prepareStatement(q);var r=p.executeQuery()){TreeSet<Long>o=new TreeSet<>();while(r.next())if(PLAYER.matcher(r.getString(2)).find())o.add(r.getLong(1));return List.copyOf(o);}}catch(SQLException e){throw new IllegalStateException(e);}}}
